import torch
for path in ['/app/weights.pt','/app/dataset.pt']:
    print('\n===', path, '===')
    obj = torch.load(path, map_location='cpu', weights_only=False)
    print('type:', type(obj))
    if isinstance(obj, dict):
        print('keys:', list(obj.keys()))
        for k,v in obj.items():
            if torch.is_tensor(v):
                print(k, 'tensor', tuple(v.shape), v.dtype, 'requires_grad=', v.requires_grad)
            else:
                print(k, type(v), repr(v)[:300])
    elif torch.is_tensor(obj):
        print('tensor', tuple(obj.shape), obj.dtype)
    elif isinstance(obj, (list,tuple)):
        print('len:', len(obj))
        for i,v in enumerate(obj[:10]):
            print(i, type(v), tuple(v.shape) if torch.is_tensor(v) else repr(v)[:200])
